async function clearStaleDunning(server: DueServer): Promise<void> {
  if (server.dunningStage === 0 && !server.dunningNextAt && !server.dunningPayUrl) return;
  const belongsToThisPeriod = server.dunningNextAt && server.dunningNextAt >= server.expiresAt!;
